/* Generated by Trae Work */
/* 笔记相册：按日期倒序展示全部打卡笔记照片（数据 = 本机记录 ∪ 云端 progress.json 合并） */
"use strict";
(function () {
  const REPO = (window.CloudAPI && CloudAPI.cfg().repo) || "3495714145/Prep-data";
  const BRANCH = (window.CloudAPI && CloudAPI.cfg().branch) || "main";

  function escHtml(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }
  function fetchTimeout(url, opts = {}, ms = 15000) {
    const c = new AbortController();
    const t = setTimeout(() => c.abort(), ms);
    return fetch(url, { ...opts, signal: c.signal }).finally(() => clearTimeout(t));
  }

  /* 云端 progress.json：公开仓库可无 Token 读取（raw → jsDelivr → API 兜底） */
  async function fetchCloudKeys() {
    const urls = [
      `https://raw.githubusercontent.com/${REPO}/${BRANCH}/progress.json`,
      `https://cdn.jsdelivr.net/gh/${REPO}@${BRANCH}/progress.json`
    ];
    for (const u of urls) {
      try {
        const res = await fetchTimeout(u);
        if (res.ok) { const j = await res.json(); if (j && j.keys) return j.keys; }
      } catch (e) { /* 换下一个源 */ }
    }
    try {
      const res = await fetchTimeout(`https://api.github.com/repos/${REPO}/contents/progress.json?ref=${BRANCH}`);
      if (res.ok) { const j = await res.json(); const bin = atob((j.content || "").replace(/\s/g, "")); return (JSON.parse(bin) || {}).keys || null; }
    } catch (e) { /* 忽略 */ }
    return null;
  }

  /* 汇总照片：{ id: {date, url, ts, label} }，云端同 id 优先（永久图床地址） */
  function collect(keys) {
    const map = {};
    const localDay = Store.get("day_log", { date: "", entries: [] });
    const localPhotos = Store.get("lesson_photos", {});
    const sources = [];
    if (keys && keys.day_log) sources.push(keys.day_log);
    sources.push(localDay);
    sources.forEach(dl => (dl.entries || []).forEach(e => {
      if (e && e.photo) map[e.id] = { date: dl.date || "", url: e.photo, ts: e.ts || "", label: e.label || "" };
    }));
    [keys && keys.lesson_photos, localPhotos].forEach(ph => ph && Object.keys(ph).forEach(id => {
      const p = ph[id];
      if (!p || !p.url) return;
      const old = map[id];
      map[id] = { date: p.date || (old && old.date) || "", url: p.url, ts: p.ts || (old && old.ts) || "", label: (old && old.label) || "" };
    }));
    return Object.keys(map).map(id => Object.assign({ id }, map[id]))
      .sort((a, b) => (b.date + (b.ts || "")).localeCompare(a.date + (a.ts || "")));
  }

  function render(items, cloudOk) {
    const root = document.getElementById("album");
    if (!items.length) {
      root.innerHTML = `<div class="notice empty">还没有打卡照片。在学习端完成小节并上传笔记照片后，这里会自动出现。</div>`;
      return;
    }
    const byDate = {};
    items.forEach(it => { (byDate[it.date || "未记录日期"] = byDate[it.date || "未记录日期"] || []).push(it); });
    const dates = Object.keys(byDate).sort((a, b) => b.localeCompare(a));
    root.innerHTML = dates.map(d => `
      <div class="card" style="margin-bottom:14px;">
        <h3>${escHtml(d)} <span class="muted" style="font-size:13px;">· ${byDate[d].length} 张</span></h3>
        <div class="photo-grid">${byDate[d].map(it => `
          <figure class="photo-cell">
            <a href="${escHtml(it.url)}" target="_blank" rel="noopener"><img src="${escHtml(it.url)}" alt="${escHtml(it.label || "笔记照片")}" loading="lazy"></a>
            <figcaption>${escHtml(it.label || "打卡笔记")}<br><span class="muted" style="font-size:12px;">${escHtml(it.ts || "")}</span></figcaption>
          </figure>`).join("")}
        </div>
      </div>`).join("") + (cloudOk ? "" : `<p class="muted">云端读取失败，当前仅显示本机记录。</p>`);
  }

  document.addEventListener("DOMContentLoaded", async () => {
    render(collect(null), false); /* 先渲染本机，立即有内容 */
    const keys = await fetchCloudKeys();
    render(collect(keys), !!keys);
  });
})();
